    let reads = 0;
    const schema = {type: 'object'};
    registry.register(
      {name: 'static', description: 'Static', get inputSchema() { reads++; return schema; }},
      async () => 'ok'
    );
    for (let i = 0; i < 10; i++) await registry.execute('static', {});
    expect(reads).toBe(1);
  });
});
